m=re.search(r'const rookieBoards=(\{.*?\});\nconst nf=',s,re.S)
if not m:
    raise SystemExit('rookieBoards not found')
boards=json.loads(m.group(1))

owner_mismatches=[]
player_mismatches=[]
for year,expected in CANONICAL.items():
    current=boards.get(year,{})
    cur_rounds=current.get('rounds',[])
    cur_owners=current.get('ownersByRound',[])
    for ri,exp_round in enumerate(expected['rounds']):
        cur_round=cur_rounds[ri] if ri < len(cur_rounds) else []
        for si,player in enumerate(exp_round):
            cur_player=cur_round[si] if si < len(cur_round) else None
            if cur_player != player:
                player_mismatches.append((year,ri+1,si+1,cur_player,player))
    for ri,exp_round in enumerate(expected['ownersByRound']):
        cur_round=cur_owners[ri] if ri < len(cur_owners) else []
        for si,owner in enumerate(exp_round):
            cur_owner=cur_round[si] if si < len(cur_round) else None
            if cur_owner != owner:
                player=expected['rounds'][ri][si]
                owner_mismatches.append((year,ri+1,si+1,player,cur_owner,owner))
    boards[year]={'rounds':expected['rounds'],'ownersByRound':expected['ownersByRound']}

print(f'Ownership mismatches corrected: {len(owner_mismatches)}')
for row in owner_mismatches:
    print('OWNER',row)
print(f'Player transcription/length mismatches corrected: {len(player_mismatches)}')
for row in player_mismatches:
    print('PLAYER',row)

# Critical source checks.
assert boards['2020']['ownersByRound'][0][0]=='Seth Miller'                 # Jonathan Taylor
assert boards['2023']['ownersByRound'][0][0]=='Travis Page'                # Bijan Robinson
assert boards['2023']['ownersByRound'][5][1]=='Travis Page'                # Puka Nacua
assert boards['2025']['ownersByRound'][2][6]=='Bo Tiller'                  # Jaxson Dart
assert boards['2025']['rounds'][2][12]=="Dont'e Thornton"
assert boards['2025']['ownersByRound'][2][12]=='Ryan Lipkin'
assert boards['2019']['rounds'][0][6]=='Diontae Johnson'
assert boards['2019']['rounds'][2][9]=='Jalen Hurd'

s=s[:m.start(1)]+json.dumps(boards,separators=(',',':'))+s[m.end(1):]
p.write_text(s)
print('Applied canonical 2019-2026 rookie draft boards from Dynasty Plebs workbook')
